using System;
using System.Reflection;

sealed class MarkAttribute : Attribute
{
    public MarkAttribute(bool a, params object[] b)
    {
        B = b;
    }
    public object[] B { get; }
}

[Mark(b: new object[] { "Hello", "World" }, a: true)]
static class Program
{
    public static void Main()
    {
        var attr = typeof(Program).GetCustomAttribute<MarkAttribute>();
        Console.Write($"B.Length={attr.B.Length}, B[0]={attr.B[0]}, B[1]={attr.B[1]}");
    }

    [Mark(true, "Hello")]
    static void M1(){}

    [Mark(false, "World", "Hello")]
    static void M2(){}

    [Mark(true)]
    static void M3(){}

    [Mark(a: true)]
    static void M4(){}

    [Mark(a: false, b: "M5")]
    static void M5(){}

    [Mark(b: "M6", a: true)]
    static void M6(){}
}

